    void talk() override { cout << "我在读报纸..." << endl; }
    void freeze() override { speed *= 0.5; cout << "读报僵尸减速50%" << endl; }
};

int main() {
    OrdinaryZombie Z1(100, 10.0);
    RoadblockZombie Z2(150, 8.0);
    MetalBucketZombie Z3(200, 6.0);
    NewspaperZombie Z4(120, 12.0);

    Zombie* zombies[] = { &Z1, &Z2, &Z3, &Z4 };
    int n = sizeof(zombies) / sizeof(zombies[0]);

    cout << "--- 僵尸群正在逼近 ---" << endl;
    for (int i = 0; i < n; i++) {
        zombies[i]->ShowInfo();
        zombies[i]->talk();
    }

    cout << "--- 寒冰射手发动攻击，僵尸群受冻 ---" << endl;
    for (int i = 0; i < n; i++) {
        zombies[i]->freeze();
        zombies[i]->ShowInfo();
    }
    return 0;
}

#include <iostream>

using std::cin;
using std::cout;
using std::endl;

template <typename T>
class Data {
private:
    T data[3];
public:
    Data() {
        cout << "请输入3个数据：" << endl;
        for (int i = 0; i < 3; i++) {
            cin >> data[i];
        }
    }
    T getMin() const; // 类体内声明
};

// 类外定义类模板的成员函数
template <typename T>
T Data<T>::getMin() const {
    T min_val = data[0];
    for (int i = 1; i < 3; i++) {
        if (data[i] < min_val) {
            min_val = data[i];
        }
    }
    return min_val;
}

int main() {
    Data<int> intData;
    cout << "最小值是：" << intData.getMin() << endl;

    Data<double> doubleData;
    cout << "极小值是：" << doubleData.getMin() << endl;
    return 0;
}

explanation:
## 1. 设计思路与要点

本题要求设计一个模板类 `Data`，类中包含一个大小固定为 `3` 的泛型数组：

```cpp
T data[3];
```

并完成以下功能：

1. 通过无参构造函数从键盘输入 3 个数据；
2. 通过成员函数 `getMin()` 计算并返回这 3 个数据中的最小值；
3. `getMin()` 可以在类体内声明，在类体外定义；
4. 模板类应当能够适用于不同类型，例如 `int`、`double` 等。

本题核心考察的是 **类模板的定义与使用**、**模板类成员函数的类外定义方式**、**泛型数组的使用** 以及 **基于比较运算的最小值查找算法**。

---

### 1.1 类模板的基本结构

模板类的基本定义形式如下：

```cpp
template <typename T>
class Data {
private:
    T data[3];
public:
    Data();
    T getMin() const;
};
```

其中：

- `template <typename T>` 表示声明一个类模板；
- `T` 是模板类型参数；
- `data[3]` 是一个大小固定为 3 的数组；
- 数组中元素的具体类型由创建对象时指定，例如：
  - `Data<int>` 表示数组元素类型为 `int`；
  - `Data<double>` 表示数组元素类型为 `double`；
  - 如果类型支持输入和比较，也可以是自定义类类型。

模板类的优点在于：  
**使用一套代码即可处理多种数据类型，避免重复编写多个功能相似的类。**

例如，如果不使用模板，可能需要分别写：

```cpp
class IntData {
private:
    int data[3];
};

class DoubleData {
private:
    double data[3];
};
```

而使用模板后，只需要写一个 `Data<T>` 即可。

---

### 1.2 数据成员 `T data[3]`

本题要求类中包含一个大小为 3 的泛型数组：

```cpp
T data[3];
```

这里的 `T` 是模板参数，因此数组元素类型不是固定的，而是在模板实例化时确定。

例如：

```cpp
Data<int> intData;
```

此时编译器会将模板中的 `T` 替换为 `int`，相当于生成了如下类型：

```cpp
class Data_int {
private:
    int data[3];
};
```

而：

```cpp
Data<double> doubleData;
```

则相当于生成：

```cpp
class Data_double {
private:
    double data[3];
};
```

需要注意的是，`T data[3]` 要求类型 `T` 可以被默认构造。  
对于 `int`、`double` 等内置类型没有问题；对于自定义类，如果没有默认构造函数，可能会导致对象创建失败。

---

### 1.3 无参构造函数的设计

题目要求在无参构造函数中通过键盘输入为数组的 3 个成员赋值。

参考代码中构造函数直接写在类体内：

```cpp
Data() {
    cout << "请输入3个数据：" << endl;
    for (int i = 0; i < 3; i++) {
        cin >> data[i];
    }
}
```

当创建对象时：

```cpp
Data<int> intData;
```

构造函数会自动调用，程序会提示输入 3 个整数。

当创建对象时：

```cpp
Data<double> doubleData;
```

构造函数也会自动调用，程序会提示输入 3 个浮点数。

该构造函数的逻辑是：

1. 输出提示信息；
2. 使用循环遍历数组下标 `0` 到 `2`；
3. 通过输入流 `cin` 将用户输入依次存入 `data[i]`。

---

### 1.4 `getMin()` 成员函数的设计

`getMin()` 用于返回数组中的最小值。

查找最小值的常见思路是线性扫描：

1. 先假设第一个元素是最小值；
2. 从第二个元素开始逐个比较；
3. 如果发现更小的元素，就更新最小值；
4. 遍历结束后返回最终的最小值。

对应代码如下：

```cpp
T min_val = data[0];

for (int i = 1; i < 3; i++) {
    if (data[i] < min_val) {
        min_val = data[i];
    }
}

return min_val;
```

该算法的时间复杂度是：

```cpp
O(3)
```

由于数组大小固定为 3，因此实际运行时间是常数级，也可以认为是：

```cpp
O(1)
```

---

### 1.5 为什么 `getMin()` 后面加 `const`

参考代码中函数声明为：

```cpp
T getMin() const;
```

这里的 `const` 表示该成员函数不会修改当前对象的数据成员。

也就是说，在 `getMin()` 内部不能对 `data` 进行修改，例如下面这样是非法的：

```cpp
T Data<T>::getMin() const {
    data[0] = data[1]; // 错误：const 成员函数中不能修改成员变量
    return data[0];
}
```

由于 `getMin()` 只是读取数组元素并计算最小值，不需要修改对象状态，因此加上 `const` 是合理且推荐的。

这样做的好处包括：

- 明确表达函数语义：只读，不修改对象；
- 允许常量对象调用该函数；
- 提高代码安全性。

例如：

```cpp
const Data<int> obj;
obj.getMin(); // 如果 getMin 不是 const，这里无法调用
```

虽然本题中由于构造函数需要输入数据，创建 `const Data<int>` 不太常见，但从设计上看，`getMin()` 仍然应当声明为 `const`。

---

### 1.6 模板参数 `T` 的隐含要求

虽然模板参数 `T` 可以代表任意类型，但本题中的代码对 `T` 实际上有一定要求。

因为构造函数中使用了：

```cpp
cin >> data[i];
```

所以 `T` 必须支持输入运算符 `>>`。

因为 `getMin()` 中使用了：

```cpp
data[i] < min_val
```

所以 `T` 必须支持小于运算符 `<`。

因为最终输出最小值时使用了：

```cpp
cout << intData.getMin() << endl;
```

所以 `T` 通常还应支持输出运算符 `<<`。

因此，本模板类适用的类型应满足：

- 可以从输入流读取；
- 可以进行 `<` 比较；
- 可以输出到输出流。

对于 `int`、`double`、`char`、`std::string` 等类型通常都可以正常使用。  
对于自定义类，需要自行重载相关运算符。

---

## 2. 参考代码深度解读

参考代码如下：

```cpp
#include <iostream>

using std::cin;
using std::cout;
using std::endl;

template <typename T>
class Data {
private:
    T data[3];
public:
    Data() {
        cout << "请输入3个数据：" << endl;
        for (int i = 0; i < 3; i++) {
            cin >> data[i];
        }
    }
    T getMin() const; // 类体内声明
};

// 类外定义类模板的成员函数
template <typename T>
T Data<T>::getMin() const {
    T min_val = data[0];
    for (int i = 1; i < 3; i++) {
        if (data[i] < min_val) {
            min_val = data[i];
        }
    }
    return min_val;
}

int main() {
    Data<int> intData;
    cout << "最小值是：" << intData.getMin() << endl;

    Data<double> doubleData;
    cout << "极小值是：" << doubleData.getMin() << endl;
    return 0;
}
```

---

### 2.1 头文件与命名空间

```cpp
#include <iostream>
```

引入标准输入输出流库，用于使用：

- `std::cin`
- `std::cout`
- `std::endl`

代码中没有使用：

```cpp
using namespace std;
```

而是选择：

```cpp
using std::cin;
using std::cout;
using std::endl;
```

这种写法更精确，只引入需要使用的名称，避免整个 `std` 命名空间污染全局作用域。

在小型题目中两种写法都能运行，但从工程实践角度看，推荐这种更克制的写法。

---

### 2.2 类模板声明

```cpp
template <typename T>
class Data {
private:
    T data[3];
public:
    Data() {
        cout << "请输入3个数据：" << endl;
        for (int i = 0; i < 3; i++) {
            cin >> data[i];
        }
    }
    T getMin() const;
};
```

这一段定义了类模板 `Data`。

重点是：

```cpp
template <typename T>
```

它告诉编译器，接下来定义的不是普通类，而是一个模板类。  
`T` 是一个类型参数，将来可以被替换成具体类型。

例如：

```cpp
Data<int> intData;
```

实例化时，`T` 被替换成 `int`。

---

### 2.3 访问控制：为什么 `data` 是 `private`

```cpp
private:
    T data[3];
```

数组被声明为私有成员，意味着类外代码不能直接访问：

```cpp
intData.data[0]; // 错误：data 是 private 成员
```

这样做符合面向对象中的封装原则：

- 内部数据由类自己管理；
- 外部只能通过公开接口访问；
- 避免外部随意修改内部数据导致对象状态不一致。

本题中，外部只需要获取最小值，因此提供一个公开成员函数：

```cpp
T getMin() const;
```

即可。

---

### 2.4 构造函数中的输入逻辑

```cpp
Data() {
    cout << "请输入3个数据：" << endl;
    for (int i = 0; i < 3; i++) {
        cin >> data[i];
    }
}
```

该构造函数是无参构造函数。创建对象时自动执行。

例如：

```cpp
Data<int> intData;
```

程序执行到这一句时，会立即输出：

```cpp
请输入3个数据：
```

然后等待用户输入 3 个整数。

如果输入：

```cpp
5 2 9
```

那么数组内容为：

```cpp
data[0] = 5;
data[1] = 2;
data[2] = 9;
```

之后调用：

```cpp
intData.getMin()
```

会返回 `2`。

---

### 2.5 为什么本题构造函数没有使用初始化列表

在 C++ 中，构造函数常见写法可以使用初始化列表，例如：

```cpp
Data() : data{ } {
    // ...
}
```

但是本题中 `data` 是一个固定大小数组，并且数组元素的值来自运行时输入：

```cpp
cin >> data[i];
```

因此需要在构造函数体中逐个输入赋值。

对于本题的内置类型数组 `T data[3]`，如果不进行值初始化，数组元素在输入前可能处于未初始化状态。  
但构造函数中会对 3 个元素全部赋值，因此不会使用未初始化值。

如果希望更加严谨，也可以写成：

```cpp
Data() : data{} {
    cout << "请输入3个数据：" << endl;
    for (int i = 0; i < 3; i++) {
        cin >> data[i];
    }
}
```

其中 `data{}` 会先将数组元素值初始化，再进行输入赋值。  
不过对本题而言不是必需的。

---

### 2.6 `getMin()` 的类体内声明

```cpp
T getMin() const;
```

这里仅声明函数，没有给出函数体。

含义是：

- 函数名为 `getMin`；
- 返回类型为 `T`；
- 不接收参数；
- 是一个 `const` 成员函数；
- 函数定义稍后在类外给出。

这种写法可以将类的接口与函数实现分开，使类结构更加清晰。

---

### 2.7 模板类成员函数的类外定义

这是本题最容易出错的地方。

参考代码中写法为：

```cpp
template <typename T>
T Data<T>::getMin() const {
    T min_val = data[0];
    for (int i = 1; i < 3; i++) {
        if (data[i] < min_val) {
            min_val = data[i];
        }
    }
    return min_val;
}
```

必须注意两点。

第一，类外定义模板成员函数时，前面必须重新写模板声明：

```cpp
template <typename T>
```

第二，作用域限定符中类名必须带模板参数：

```cpp
Data<T>::getMin()
```

不能写成：

```cpp
T Data::getMin() const // 错误
```

因为 `Data` 不是一个具体类型，而是一个类模板。  
真正的类型是 `Data<int>`、`Data<double>` 等，所以定义时需要写成 `Data<T>`。

完整格式为：

```cpp
template <typename T>
返回类型 类模板名<T>::函数名(参数列表) const {
    // 函数体
}
```

即：

```cpp
template <typename T>
T Data<T>::getMin() const {
    // ...
}
```

---

### 2.8 `getMin()` 中的最小值查找逻辑

```cpp
T min_val = data[0];
```

先将第一个元素作为当前最小值。

然后从第二个元素开始比较：

```cpp
for (int i = 1; i < 3; i++) {
    if (data[i] < min_val) {
        min_val = data[i];
    }
}
```

如果发现 `data[i]` 更小，则更新：

```cpp
min_val = data[i];
```

最后返回：

```cpp
return min_val;
```

以整数输入为例：

```cpp
8 3 6
```

执行过程如下：

| 步骤 | 当前元素 | 当前最小值 |
|---|---:|---:|
| 初始 | data[0] = 8 | 8 |
| 比较 data[1] | 3 < 8，更新 | 3 |
| 比较 data[2] | 6 < 3，不更新 | 3 |

最终返回：

```cpp
3
```

---

### 2.9 返回类型为什么是 `T`

```cpp
T getMin() const;
```

因为数组元素类型是 `T`，最小值也应该是同样的类型。

例如：

```cpp
Data<int>
```

最小值是 `int`。

```cpp
Data<double>
```

最小值是 `double`。

所以返回类型写成模板参数 `T` 是合理的。

---

### 2.10 返回值方式：按值返回

参考代码中：

```cpp
return min_val;
```

是按值返回。

对于 `int`、`double` 这样的小型类型，按值返回效率很高。

对于较大的自定义对象，按值返回可能会产生拷贝开销。现代 C++ 编译器通常可以通过返回值优化或移动语义降低开销。  
如果进一步优化，也可以考虑返回引用：

```cpp
const T& getMin() const;
```

不过本题中返回值 `min_val` 是局部变量，如果写成引用返回：

```cpp
const T& Data<T>::getMin() const {
    T min_val = data[0];
    return min_val; // 严重错误：返回局部变量引用
}
```

这是错误的，因为 `min_val` 在函数结束后会被销毁，返回引用会悬空。

若要安全返回引用，需要记录最小元素下标，返回数组中元素的引用，例如：

```cpp
template <typename T>
const T& Data<T>::getMin() const {
    int minIndex = 0;
    for (int i = 1; i < 3; i++) {
        if (data[i] < data[minIndex]) {
            minIndex = i;
        }
    }
    return data[minIndex];
}
```

但本题要求返回 `T`，因此按值返回即可。

---

### 2.11 主函数测试模板实例化

```cpp
int main() {
    Data<int> intData;
    cout << "最小值是：" << intData.getMin() << endl;

    Data<double> doubleData;
    cout << "极小值是：" << doubleData.getMin() << endl;
    return 0;
}
```

这里创建了两个对象：

```cpp
Data<int> intData;
Data<double> doubleData;
```

它们是同一个类模板生成的两个不同类型。

编译器会分别根据模板生成适用于 `int` 和 `double` 的代码。  
这就是模板实例化。

例如：

```cpp
Data<int>
```

中的 `T` 被替换成 `int`：

```cpp
int data[3];
int getMin() const;
```

而：

```cpp
Data<double>
```

中的 `T` 被替换成 `double`：

```cpp
double data[3];
double getMin() const;
```

这体现了模板的泛型编程思想。

---

### 2.12 一次可能的运行示例

程序运行时可能如下：

```text
请输入3个数据：
5 2 9
最小值是：2
请输入3个数据：
3.14 2.71 6.28
极小值是：2.71
```

说明：

- 第一次创建 `Data<int>` 对象，需要输入 3 个整数；
- 第二次创建 `Data<double>` 对象，需要输入 3 个浮点数；
- 两次调用 `getMin()` 分别得到不同类型数据的最小值。

