    // 构造函数不能有返回值类型，推荐使用成员初始化列表
    Date(int y, int m, int d) : year(y), month(m), day(d) {
        if (month < 1 || month > 12) {
            month = 1;
        }
        if (day < 1 || day > 31) {
            day = 1;
        }
    }

    void show() const {
        cout << year << '-' << month << '-' << day << endl;
    }
};

