#include <iostream>
#include <vector>
#include <memory>
#include <cmath>
#include <iomanip>
using namespace std;

// 抽象基类 Shape
class Shape {
public:
    virtual ~Shape() = default;

    // 纯虚函数：计算面积
    virtual double Area() const = 0;

    // 纯虚函数：显示图形信息
    virtual void Show() const = 0;
};

// 圆形类
class Circle : public Shape {
private:
    double radius;

public:
    explicit Circle(double r) : radius(r) {}

    double Area() const override {
        const double PI = acos(-1.0);
        return PI * radius * radius;
    }

    void Show() const override {
        cout << "Circle: radius = " << radius
             << ", area = " << Area() << endl;
    }
};

// 矩形类
class Rectangle : public Shape {
private:
    double length;
    double width;

public:
    Rectangle(double l, double w) : length(l), width(w) {}

    double Area() const override {
        return length * width;
    }

    void Show() const override {
        cout << "Rectangle: length = " << length
             << ", width = " << width
             << ", area = " << Area() << endl;
    }
};

int main() {
    cout << fixed << setprecision(2);

    vector<unique_ptr<Shape>> shapes;

    // 创建不同图形对象
    shapes.push_back(make_unique<Circle>(3.0));
    shapes.push_back(make_unique<Rectangle>(4.0, 5.0));
    shapes.push_back(make_unique<Circle>(2.5));
    shapes.push_back(make_unique<Rectangle>(6.0, 2.0));

    double totalArea = 0.0;

    cout << "各图形信息如下：" << endl;
    for (const auto &shape : shapes) {
        shape->Show();
        totalArea += shape->Area();
    }

    cout << "所有图形的总面积 = " << totalArea << endl;

    return 0;
}

#include <iostream>
using namespace std;

const double PI = 3.1415926;

class Shape
{
public:
    Shape() { }
    virtual ~Shape() { }
    virtual void ShowArea() = 0;
    static double totalArea;
    static void ShowTotalArea()
    {
        cout << "总面积:" << totalArea << endl;
    }
};

double Shape::totalArea = 0;

class Circle : public Shape
{
private:
    double radius;

public:
    Circle(double r) : radius(r)
    {
        totalArea += PI * r * r;
    }

    ~Circle() { }

    virtual void ShowArea()
    {
        cout << "圆面积:" << PI * radius * radius << endl;
    }
};

class Rectangle : public Shape
{
private:
    double length;
    double width;

public:
    Rectangle(double l, double w) : length(l), width(w)
    {
        totalArea += l * w;
    }

    ~Rectangle() { }

    virtual void ShowArea()
    {
        cout << "矩形面积:" << length * width << endl;
    }
};

class Square : public Shape
{
private:
    double side;

public:
    Square(double s) : side(s)
    {
        totalArea += s * s;
    }

    ~Square() { }

    virtual void ShowArea()
    {
        cout << "正方形面积:" << side * side << endl;
    }
};

int main()
{
    Shape* p[3];

    p[0] = new Circle(2.0);
    p[1] = new Rectangle(3.0, 4.0);
    p[2] = new Square(5.0);

    for (int i = 0; i < 3; ++i)
    {
        p[i]->ShowArea();
    }

    Shape::ShowTotalArea();

    for (int i = 0; i < 3; ++i)
    {
        delete p[i];
    }

    return 0;
}

explanation:
## 1. **设计思路与要点**

本题考查 C++ 面向对象程序设计中非常典型的几个知识点：

- 抽象基类与纯虚函数
- 继承与派生
- 运行时多态
- 虚析构函数
- 静态成员变量与静态成员函数
- 基类指针管理派生类对象

题目要求定义一个抽象基类 `Shape`，并由它派生出 `Circle`、`Rectangle`、`Square` 三个具体图形类。每个派生类都需要计算并显示自己的面积，同时还要统计所有图形对象的总面积。

---

### 1.1 抽象基类 `Shape` 的设计

```cpp
class Shape
{
public:
    Shape() { }
    virtual ~Shape() { }
    virtual void ShowArea() = 0;
    static double totalArea;
    static void ShowTotalArea()
    {
        cout << "总面积:" << totalArea << endl;
    }
};
```

`Shape` 被设计为抽象基类，核心原因在于：

- “图形”本身是一个抽象概念；
- 不同图形计算面积的公式不同；
- 基类无法给出统一的面积计算实现；
- 但所有图形都应具备“显示面积”这一公共行为。

因此，在 `Shape` 中定义纯虚函数：

```cpp
virtual void ShowArea() = 0;
```

这表示：

1. `ShowArea()` 是一个虚函数；
2. `= 0` 表示它是纯虚函数；
3. 含有纯虚函数的类是抽象类；
4. 抽象类不能直接实例化对象。

例如，以下代码是非法的：

```cpp
Shape s;       // 错误：Shape 是抽象类，不能实例化
```

但可以定义基类指针或引用：

```cpp
Shape* p;
Shape& ref = someShapeObject;
```

这正是实现多态的基础。

---

### 1.2 派生类重写 `ShowArea()`

三个派生类分别表示具体图形：

```cpp
class Circle : public Shape
class Rectangle : public Shape
class Square : public Shape
```

它们都必须实现基类中的纯虚函数 `ShowArea()`，否则它们自身也会成为抽象类，仍然不能创建对象。

例如圆类中实现：

```cpp
virtual void ShowArea()
{
    cout << "圆面积:" << PI * radius * radius << endl;
}
```

矩形类中实现：

```cpp
virtual void ShowArea()
{
    cout << "矩形面积:" << length * width << endl;
}
```

正方形类中实现：

```cpp
virtual void ShowArea()
{
    cout << "正方形面积:" << side * side << endl;
}
```

这样，虽然调用形式都是：

```cpp
p[i]->ShowArea();
```

但程序会根据 `p[i]` 实际指向的对象类型，动态调用对应类的 `ShowArea()` 函数。

这就是 C++ 的运行时多态。

---

### 1.3 为什么基类析构函数要声明为 `virtual`

参考代码中：

```cpp
virtual ~Shape() { }
```

这是非常重要的设计。

主函数中使用的是基类指针数组：

```cpp
Shape* p[3];
```

然后让这些基类指针分别指向派生类对象：

```cpp
p[0] = new Circle(2.0);
p[1] = new Rectangle(3.0, 4.0);
p[2] = new Square(5.0);
```

最后通过基类指针释放对象：

```cpp
delete p[i];
```

如果基类析构函数不是虚函数，那么通过基类指针删除派生类对象时，通常只会调用基类析构函数，而派生类析构函数可能不会被正确调用。这会导致资源释放不完整，产生内存泄漏或未定义行为。

正确做法是：

```cpp
virtual ~Shape() { }
```

即使本题中派生类没有动态申请额外资源，也应该将作为多态基类的析构函数声明为虚函数。这是 C++ OOP 中的重要最佳实践。

---

### 1.4 静态成员变量 `totalArea` 的作用

题目要求显示所有图形的总面积，因此需要一个被所有图形对象共享的数据。

参考代码在 `Shape` 中定义：

```cpp
static double totalArea;
```

静态成员变量属于类本身，而不是某个具体对象。也就是说：

- 所有 `Circle`、`Rectangle`、`Square` 对象共享同一个 `Shape::totalArea`；
- 每创建一个图形对象，就将该对象面积累加到 `totalArea`；
- 最后通过静态成员函数输出总面积。

在类内声明静态成员变量后，还必须在类外进行定义和初始化：

```cpp
double Shape::totalArea = 0;
```

这一句不可省略。类内的：

```cpp
static double totalArea;
```

只是声明，表示类中存在这样一个静态成员；而类外的：

```cpp
double Shape::totalArea = 0;
```

才是真正分配存储空间并初始化。

如果缺少该定义，通常会出现链接错误，例如：

```text
undefined reference to `Shape::totalArea`
```

---

### 1.5 静态成员函数 `ShowTotalArea()`

```cpp
static void ShowTotalArea()
{
    cout << "总面积:" << totalArea << endl;
}
```

静态成员函数同样属于类，而不是某个对象。调用方式可以是：

```cpp
Shape::ShowTotalArea();
```

也可以通过对象调用，但更推荐使用类名调用，因为语义更清晰。

需要注意的是，静态成员函数没有 `this` 指针，因此它不能直接访问非静态成员变量或非静态成员函数。

例如下面的写法是不允许的：

```cpp
static void ShowTotalArea()
{
    cout << radius << endl;   // 错误：radius 是 Circle 对象的非静态成员
}
```

但访问静态成员变量 `totalArea` 是合法的：

```cpp
cout << totalArea << endl;
```

---

## 2. **参考代码深度解读**

下面结合题目参考代码逐段分析其实现细节。

---

### 2.1 头文件与常量定义

```cpp
#include <iostream>
using namespace std;

const double PI = 3.1415926;
```

`#include <iostream>` 用于输入输出操作。

`PI` 被定义为全局常量：

```cpp
const double PI = 3.1415926;
```

它用于圆面积公式：

```cpp
PI * r * r
```

在现代 C++ 中，也可以进一步写成：

```cpp
constexpr double PI = 3.1415926;
```

`constexpr` 表示该值是编译期常量，语义更加明确。

---

### 2.2 抽象基类 `Shape`

```cpp
class Shape
{
public:
    Shape() { }
    virtual ~Shape() { }
    virtual void ShowArea() = 0;
    static double totalArea;
    static void ShowTotalArea()
    {
        cout << "总面积:" << totalArea << endl;
    }
};
```

该类包含三个核心部分：

#### 第一，构造函数

```cpp
Shape() { }
```

基类构造函数会在派生类对象构造时先被调用。虽然本题中它没有执行具体操作，但保留默认构造函数是合理的。

也可以写成：

```cpp
Shape() = default;
```

#### 第二，虚析构函数

```cpp
virtual ~Shape() { }
```

保证通过 `Shape*` 删除派生类对象时能够正确析构。

也可以写成：

```cpp
virtual ~Shape() = default;
```

#### 第三，纯虚函数

```cpp
virtual void ShowArea() = 0;
```

该函数强制派生类提供具体实现。

更现代的写法是在派生类中使用 `override` 明确标识重写：

```cpp
void ShowArea() override
```

这能让编译器检查函数签名是否真的覆盖了基类虚函数。

---

### 2.3 静态成员变量类外定义

```cpp
double Shape::totalArea = 0;
```

这是本题中一个非常关键的语法点。

静态成员变量在类内只是声明：

```cpp
static double totalArea;
```

必须在类外定义：

```cpp
double Shape::totalArea = 0;
```

其中：

- `double` 是变量类型；
- `Shape::` 表示该变量属于 `Shape` 类；
- `= 0` 是初始化。

如果把它误写成下面这样：

```cpp
static double Shape::totalArea = 0;  // 错误
```

通常是不正确的，因为类外定义静态成员时不再使用 `static` 关键字。

---

### 2.4 `Circle` 类设计

```cpp
class Circle : public Shape
{
private:
    double radius;

public:
    Circle(double r) : radius(r)
    {
        totalArea += PI * r * r;
    }

    ~Circle() { }

    virtual void ShowArea()
    {
        cout << "圆面积:" << PI * radius * radius << endl;
    }
};
```

圆类私有成员：

```cpp
double radius;
```

表示半径。

构造函数使用初始化列表：

```cpp
Circle(double r) : radius(r)
```

这比在构造函数体内赋值更推荐。

例如：

```cpp
Circle(double r)
{
    radius = r;
}
```

这属于先默认初始化，再赋值。

而初始化列表：

```cpp
Circle(double r) : radius(r)
```

是在对象构造阶段直接初始化成员，更高效，也更符合 C++ 对象初始化语义。

构造函数体中：

```cpp
totalArea += PI * r * r;
```

将当前圆对象的面积加入总面积。

由于 `totalArea` 是从基类继承而来的静态成员，因此在派生类中可以直接访问。为了语义更清晰，也可以写成：

```cpp
Shape::totalArea += PI * r * r;
```

面积显示函数：

```cpp
virtual void ShowArea()
{
    cout << "圆面积:" << PI * radius * radius << endl;
}
```

这里通过虚函数重写实现圆的面积输出。

更推荐的现代写法：

```cpp
void ShowArea() override
{
    cout << "圆面积:" << PI * radius * radius << endl;
}
```

`override` 的好处是，如果误写函数名或参数类型，编译器会报错。

例如：

```cpp
void showArea() override  // 错误：大小写不同，没有覆盖基类函数
```

---

### 2.5 `Rectangle` 类设计

```cpp
class Rectangle : public Shape
{
private:
    double length;
    double width;

public:
    Rectangle(double l, double w) : length(l), width(w)
    {
        totalArea += l * w;
    }

    ~Rectangle() { }

    virtual void ShowArea()
    {
        cout << "矩形面积:" << length * width << endl;
    }
};
```

矩形包含两个数据成员：

```cpp
double length;
double width;
```

分别表示长和宽。

构造函数：

```cpp
Rectangle(double l, double w) : length(l), width(w)
{
    totalArea += l * w;
}
```

初始化列表按照类中成员声明顺序进行初始化，而不是按照初始化列表书写顺序。

这里类中成员顺序是：

```cpp
double length;
double width;
```

因此先初始化 `length`，再初始化 `width`。

面积计算公式：

```cpp
length * width
```

在构造时加入总面积，在 `ShowArea()` 中输出自身面积。

---

### 2.6 `Square` 类设计

```cpp
class Square : public Shape
{
private:
    double side;

public:
    Square(double s) : side(s)
    {
        totalArea += s * s;
    }

    ~Square() { }

    virtual void ShowArea()
    {
        cout << "正方形面积:" << side * side << endl;
    }
};
```

正方形只需要一个数据成员：

```cpp
double side;
```

构造函数：

```cpp
Square(double s) : side(s)
{
    totalArea += s * s;
}
```

面积公式为：

```cpp
side * side
```

同样，创建对象时累加面积，调用 `ShowArea()` 时显示面积。

---

### 2.7 主函数中的多态调用

```cpp
int main()
{
    Shape* p[3];

    p[0] = new Circle(2.0);
    p[1] = new Rectangle(3.0, 4.0);
    p[2] = new Square(5.0);

    for (int i = 0; i < 3; ++i)
    {
        p[i]->ShowArea();
    }

    Shape::ShowTotalArea();

    for (int i = 0; i < 3; ++i)
    {
        delete p[i];
    }

    return 0;
}
```

这里定义了基类指针数组：

```cpp
Shape* p[3];
```

每个元素都是 `Shape*` 类型，但可以指向任意 `Shape` 派生类对象。

```cpp
p[0] = new Circle(2.0);
p[1] = new Rectangle(3.0, 4.0);
p[2] = new Square(5.0);
```

这体现了继承中的“向上转型”：

- `Circle*` 可以转换为 `Shape*`
- `Rectangle*` 可以转换为 `Shape*`
- `Square*` 可以转换为 `Shape*`

随后通过统一接口调用：

```cpp
p[i]->ShowArea();
```

由于 `ShowArea()` 是虚函数，程序运行时会根据对象真实类型调用相应版本：

- `p[0]->ShowArea()` 调用 `Circle::ShowArea()`
- `p[1]->ShowArea()` 调用 `Rectangle::ShowArea()`
- `p[2]->ShowArea()` 调用 `Square::ShowArea()`

这就是动态绑定，也称运行时多态。

---

### 2.8 程序运行结果分析

各图形面积如下：

圆半径为 `2.0`：

```cpp
PI * 2.0 * 2.0 = 3.1415926 * 4 = 12.5663704
```

矩形长宽分别为 `3.0` 和 `4.0`：

```cpp
3.0 * 4.0 = 12
```

正方形边长为 `5.0`：

```cpp
5.0 * 5.0 = 25
```

总面积：

```cpp
12.5663704 + 12 + 25 = 49.5663704
```

因此可能输出：

```text
圆面积:12.5664
矩形面积:12
正方形面积:25
总面积:49.5664
```

实际小数位数取决于 `cout` 默认输出精度。

---

## 3. **避坑指南与最佳实践**

---

### 3.1 静态成员变量只在类内声明，忘记类外定义

错误示例：

```cpp
class Shape
{
public:
    static double totalArea;
};
```

如果没有下面这一句：

```cpp
double Shape::totalArea = 0;
```

程序可能编译通过，但链接阶段会报错。

正确写法：

```cpp
class Shape
{
public:
    static double totalArea;
};

double Shape::totalArea = 0;
```

这是因为非 `inline` 静态数据成员需要在类外定义一次。

在 C++17 及以后，也可以使用 `inline static`：

```cpp
class Shape
{
public:
    inline static double totalArea = 0;
};
```

这样就不需要再在类外定义。

---

### 3.2 基类析构函数忘记声明为虚函数

错误示例：

```cpp
class Shape
{
public:
    ~Shape() { }
    virtual void ShowArea() = 0;
};
```

然后：

```cpp
Shape* p = new Circle(2.0);
delete p;
```

如果析构函数不是虚函数，通过基类指针删除派生类对象会产生未定义行为，派生类析构函数可能不会被调用。

正确写法：

```cpp
class Shape
{
public:
    virtual ~Shape() { }
};
```

或：

```cpp
virtual ~Shape() = default;
```

只要一个类被设计为多态基类，析构函数通常就应该是虚函数。

---

### 3.3 派生类忘记实现纯虚函数

错误示例：

```cpp
class Circle : public Shape
{
private:
    double radius;
public:
    Circle(double r) : radius(r) { }
};
```

由于 `Shape` 中有：

```cpp
virtual void ShowArea() = 0;
```

如果 `Circle` 没有实现它，那么 `Circle` 仍然是抽象类，不能创建对象：

```cpp
Circle c(2.0);  // 错误
```

正确写法：

```cpp
void ShowArea() override
{
    cout << "圆面积:" << PI * radius * radius << endl;
}
```

---

### 3.4 函数签名不一致导致没有真正重写

错误示例：

```cpp
void Showarea()
{
    cout << "圆面积" << endl;
}
```

这里 `Showarea` 和 `ShowArea` 大小写不同，不是同一个函数。

又如：

```cpp
void ShowArea() const
{
    cout << "圆面积" << endl;
}
```

如果基类声明为：

```cpp
virtual void ShowArea() = 0;
```

那么派生类中的 `void ShowArea() const` 也不是对它的重写，因为多了 `const` 限定。

建议写成：

```cpp
void ShowArea() override
{
    cout << "圆面积:" << PI * radius * radius << endl;
}
```

使用 `override` 后，如果没有真正覆盖基类虚函数，编译器会直接报错。

---

### 3.5 面积统计放在构造函数中的潜在问题

参考代码在各派生类构造函数中累加总面积：

```cpp
totalArea += PI * r * r;
```

这种做法简单直观，适合本题。

但需要注意：如果对象被复制，可能会造成总面积统计不符合预期。

例如：

```cpp
Circle c1(2.0);
Circle c2 = c1;
```

如果没有自定义拷贝构造函数，`c2` 会被复制出来，但总面积不会自动增加，因为默认拷贝构造函数不会执行 `Circle(double r)` 中的累加逻辑。

反过来，如果手动在拷贝构造函数中也累加面积，又要考虑析构时是否减少面积。

如果要把 `totalArea` 设计成“当前存活对象的面积总和”，那么构造函数中加面积，析构函数中就应减面积：

```cpp
~Circle()
{
    totalArea -= PI * radius * radius;
}
```

但本题要求更像是“已创建图形的面积总和”，因此析构时不减面积也是可以接受的。

关键是要明确统计口径：

- 如果统计“创建过的所有图形总面积”，析构时不减；
- 如果统计“当前存在的所有图形总面积”，析构时应减。

本题参考代码采用的是前者。

---

### 3.6 使用裸指针和 `new/delete` 要注意资源释放

参考代码中：

```cpp
p[0] = new Circle(2.0);
p[1] = new Rectangle(3.0, 4.0);
p[2] = new Square(5.0);
```

最后必须释放：

```cpp
for (int i = 0; i < 3; ++i)
{
    delete p[i];
}
```

如果忘记 `delete`，就会造成内存泄漏。

现代 C++ 中更推荐使用智能指针，例如：

```cpp
#include <memory>
#include <vector>

vector<unique_ptr<Shape>> shapes;

shapes.push_back(make_unique<Circle>(2.0));
shapes.push_back(make_unique<Rectangle>(3.0, 4.0));
shapes.push_back(make_unique<Square>(5.0));

for (const auto& shape : shapes)
{
    shape->ShowArea();
}

Shape::ShowTotalArea();
```

这样可以自动释放内存，避免手动 `delete`。

---

### 3.7 `ShowArea()` 更适合声明为 `const`

本题中的 `ShowArea()` 只是输出面积，不应该修改对象状态，因此更严谨的接口设计是：

```cpp
virtual void ShowArea() const = 0;
```

派生类对应写成：

```cpp
void ShowArea() const override
{
    cout << "圆面积:" << PI * radius * radius << endl;
}
```

这样可以保证该函数不会修改成员变量，也允许通过 `const Shape*` 或 `const Shape&` 调用。

例如：

```cpp
const Shape* p = new Circle(2.0);
p->ShowArea();
```

如果 `ShowArea()` 没有声明为 `const`，则不能通过 `const Shape*` 调用。

---

### 3.8 面积计算逻辑可以进一步抽象

参考代码中，面积计算分别写在构造函数和 `ShowArea()` 中：

```cpp
totalArea += PI * r * r;
cout << "圆面积:" << PI * radius * radius << endl;
```

这会导致面积公式重复出现。

更好的做法是定义一个虚函数 `Area()`，专门返回面积：

```cpp
virtual double Area() const = 0;
```

然后 `ShowArea()` 可以基于 `Area()` 实现。

例如：

```cpp
class Shape
{
public:
    virtual ~Shape() = default;
    virtual double Area() const = 0;
    virtual void ShowArea() const = 0;

    static double totalArea;
};
```

在 `Circle` 中：

```cpp
double Area() const override
{
    return PI * radius * radius;
}

void ShowArea() const override
{
    cout << "圆面积:" << Area() << endl;
}
```

这样有几个好处：

- 面积计算逻辑只写一处；
- 便于后续扩展；
- 更符合单一职责原则；
- 若需要排序、统计、筛选面积，也可以直接调用 `Area()`。

---

### 3.9 对输入参数进行合法性检查

本题参考代码没有检查半径、长宽、边长是否为负数。

例如：

```cpp
Circle c(-2.0);
```

从数学意义上讲，半径不能为负。

实际工程代码中应进行参数校验：

```cpp
Circle(double r) : radius(r)
{
    if (r < 0)
    {
        throw invalid_argument("radius cannot be negative");
    }
    totalArea += PI * r * r;
}
```

但要注意，检查应该放在使用参数计算面积之前。更严谨写法是：

```cpp
Circle(double r) : radius(r)
{
    if (radius < 0)
    {
        throw invalid_argument("radius cannot be negative");
    }
    totalArea += PI * radius * radius;
}
```

矩形和正方形同理。

---

### 3.10 推荐的现代 C++ 改进版示例

在保持题意不变的前提下，可以写成如下更现代、更安全的版本：

```cpp
#include <iostream>
#include <memory>
#include <vector>
using namespace std;

constexpr double PI = 3.1415926;

class Shape
{
public:
    Shape() = default;
    virtual ~Shape() = default;

    virtual double Area() const = 0;
    virtual void ShowArea() const = 0;

    inline static double totalArea = 0;

    static void ShowTotalArea()
    {
        cout << "总面积:" << totalArea << endl;
    }
};

class Circle : public Shape
{
private:
    double radius;

public:
    explicit Circle(double r) : radius(r)
    {
        totalArea += Area();
    }

    double Area() const override
    {
        return PI * radius * radius;
    }

    void ShowArea() const override
    {
        cout << "圆面积:" << Area() << endl;
    }
};

class Rectangle : public Shape
{
private:
    double length;
    double width;

public:
    Rectangle(double l, double w) : length(l), width(w)
    {
        totalArea += Area();
    }

    double Area() const override
    {
        return length * width;
    }

    void ShowArea() const override
    {
        cout << "矩形面积:" << Area() << endl;
    }
};

class Square : public Shape
{
private:
    double side;

public:
    explicit Square(double s) : side(s)
    {
        totalArea += Area();
    }

    double Area() const override
    {
        return side * side;
    }

    void ShowArea() const override
    {
        cout << "正方形面积:" << Area() << endl;
    }
};

int main()
{
    vector<unique_ptr<Shape>> shapes;

    shapes.push_back(make_unique<Circle>(2.0));
    shapes.push_back(make_unique<Rectangle>(3.0, 4.0));
    shapes.push_back(make_unique<Square>(5.0));

    for (const auto& shape : shapes)
    {
        shape->ShowArea();
    }

    Shape::ShowTotalArea();

    return 0;
}
```

该版本相比参考代码有以下改进：

- 使用 `override` 提高重写安全性；
- 使用 `const` 成员函数保证显示面积时不修改对象；
- 使用 `Area()` 避免面积公式重复；
- 使用 `inline static` 简化静态成员初始化；
- 使用 `unique_ptr` 避免手动 `delete`；
- 使用 `vector` 提高容器扩展性；
- 使用 `constexpr` 表示编译期常量；
- 使用 `explicit` 防止单参数构造函数发生隐式类型转换。

---

### 3.11 本题核心总结

本题的关键在于：

1. `Shape` 应设计为抽象基类，使用纯虚函数 `ShowArea()` 统一接口；
2. `Circle`、`Rectangle`、`Square` 通过继承实现各自面积输出；
3. 使用基类指针数组 `Shape* p[3]` 管理不同派生类对象；
4. 通过虚函数实现运行时多态；
5. 基类析构函数必须声明为 `virtual`；
6. 静态成员变量 `totalArea` 需要在类内声明、类外定义；
7. 构造派生类对象时累加面积，最后通过 `Shape::ShowTotalArea()` 输出总面积；
8. 使用完 `new` 创建的对象后必须 `delete`，否则会造成内存泄漏。

